any_string_type = (bytes, str)


class NotConstant:
    _obj = None

    def __new__(cls):
        if NotConstant._obj is None:
            NotConstant._obj = super().__new__(cls)

        return NotConstant._obj

    def __repr__(self):
        return "<NOT CONSTANT>"

not_a_constant = NotConstant()
constant_value_not_set = object()

def _type_to_itself(tp):
    return tp, tp

